SELECT v.label AS "Поле",v.value AS "Значение" FROM (SELECT t.id AS "Номер",t.description AS "Описание",t.client_name AS "Клиент",c.name AS "Компания",CASE t.status WHEN 'new' THEN 'Новая' WHEN 'in_progress' THEN 'В работе' WHEN 'waiting_client' THEN 'Ожидает клиента' WHEN 'closed' THEN 'Закрыта' WHEN 'cancelled' THEN 'Отменена' ELSE 'Нет данных' END AS "Статус",d.name AS "Текущий отдел",u.name AS "Исполнитель",
 t.created_at AT TIME ZONE 'Asia/Irkutsk' AS "Создана",t.updated_at AT TIME ZONE 'Asia/Irkutsk' AS "Изменена",
 t.cycle_started_at AT TIME ZONE 'Asia/Irkutsk' AS "Текущий цикл",t.first_response_at AT TIME ZONE 'Asia/Irkutsk' AS "Первый ответ текущего цикла",
 round(extract(epoch FROM (r.snapshot_at-t.created_at))/3600.0,2) AS "Полный возраст, кал. ч",t.incomplete AS "Неполная история",t.quality AS "Ограничения"
FROM analytics.tickets t LEFT JOIN analytics.companies c ON c.id=t.company_id LEFT JOIN analytics.departments d ON d.code=t.department LEFT JOIN analytics.employees u ON u.id=t.assignee_id CROSS JOIN analytics.refresh_state r
WHERE r.id=1 AND t.id={{ticket_id}}) d CROSS JOIN LATERAL (VALUES (0,'Номер',d."Номер"::text),(1,'Описание',d."Описание"::text),(2,'Клиент',d."Клиент"::text),(3,'Компания',d."Компания"::text),(4,'Статус',d."Статус"::text),(5,'Текущий отдел',d."Текущий отдел"::text),(6,'Исполнитель',d."Исполнитель"::text),(7,'Создана',to_char(d."Создана",'DD.MM.YYYY HH24:MI')),(8,'Изменена',to_char(d."Изменена",'DD.MM.YYYY HH24:MI')),(9,'Текущий цикл',to_char(d."Текущий цикл",'DD.MM.YYYY HH24:MI')),(10,'Первый ответ текущего цикла',to_char(d."Первый ответ текущего цикла",'DD.MM.YYYY HH24:MI')),(11,'Полный возраст, кал. ч',d."Полный возраст, кал. ч"::text),(12,'Неполная история',CASE WHEN d."Неполная история" THEN 'Да' ELSE 'Нет' END),(13,'Ограничения',CASE WHEN d."Ограничения"='complete' THEN 'Без выявленных пробелов' ELSE d."Ограничения" END)) v(position,label,value) ORDER BY v.position
